/**
 * "HOP City" — the offline basemap. Rendered from /map/hop-city.json (a
 * stylised, procedural Gush Dan generated by scripts/gen-city.mjs) whenever
 * real vector tiles are unavailable. Sea, beach, parks, the Yarkon, roads by
 * class and extruded buildings, lit for a pitched 3D camera. It is a schematic,
 * not survey data, and the map says so on screen.
 */
import type { StyleSpecification } from "maplibre-gl";

export type MapTheme = "light" | "dark";

type Palette = {
  land: string;
  sea: string;
  seaEdge: string;
  beach: string;
  park: string;
  parkEdge: string;
  river: string;
  casing: string;
  road: string;
  highway: string;
  highwayCasing: string;
  buildingLow: string;
  buildingMid: string;
  buildingHigh: string;
  sky: string;
  horizon: string;
  fog: string;
};

const PALETTES: Record<MapTheme, Palette> = {
  light: {
    land: "#eef1f6",
    sea: "#cddcff",
    seaEdge: "#b7cbff",
    beach: "#f4efe3",
    park: "#d7eedd",
    parkEdge: "#c3e3cc",
    river: "#bcd0ff",
    casing: "#dde2eb",
    road: "#ffffff",
    highway: "#ffffff",
    highwayCasing: "#c4cfee",
    buildingLow: "#f3f5f9",
    buildingMid: "#e2e7f2",
    buildingHigh: "#bccbf4",
    sky: "#cfdcff",
    horizon: "#eef2fb",
    fog: "#eef1f6",
  },
  dark: {
    land: "#141820",
    sea: "#0e1a36",
    seaEdge: "#1a2c5c",
    beach: "#1d1f26",
    park: "#13251c",
    parkEdge: "#183024",
    river: "#173064",
    casing: "#0b0d12",
    road: "#262c3b",
    highway: "#2e3854",
    highwayCasing: "#0b0d12",
    buildingLow: "#1d222e",
    buildingMid: "#252c3e",
    buildingHigh: "#2f3f74",
    sky: "#0b1022",
    horizon: "#1b2340",
    fog: "#141820",
  },
};

const kind = (k: string) => ["==", ["get", "kind"], k] as ["==", ["get", string], string];
const roadClass = (c: string) => ["all", kind("road"), ["==", ["get", "class"], c]] as unknown as ["all"];

/** Zoom-interpolated line width: [zoom, width] pairs. */
const w = (...stops: [number, number][]) => ["interpolate", ["exponential", 1.6], ["zoom"], ...stops.flat()] as unknown as number;

export const CITY_ATTRIBUTION = "מפה סכמטית © HOP";

type Feature = { type: "Feature"; properties: Record<string, unknown>; geometry: { type: string; coordinates: unknown } };
export type FeatureCollection = { type: "FeatureCollection"; features: Feature[] };
type CityFile = FeatureCollection & { hop?: { gridAngle: number; buildings: number[] } };

let cityData: Promise<FeatureCollection> | null = null;

/**
 * Fetches the city once per page and expands its compact building tuples
 * ([lng, lat, width m, depth m, height m], aligned to the street grid) into
 * rotated footprint polygons.
 */
export function loadCityData(url: string): Promise<FeatureCollection> {
  cityData ??= fetch(url)
    .then((r) => {
      if (!r.ok) throw new Error(`city ${r.status}`);
      return r.json() as Promise<CityFile>;
    })
    .then((file) => {
      const features = file.features.slice();
      const b = file.hop?.buildings ?? [];
      const th = ((file.hop?.gridAngle ?? 0) * Math.PI) / 180;
      const cos = Math.cos(th);
      const sin = Math.sin(th);
      const mLat = 110_540;
      for (let i = 0; i + 4 < b.length; i += 5) {
        const lng = b[i];
        const lat = b[i + 1];
        const hw = b[i + 2] / 2;
        const hd = b[i + 3] / 2;
        const mLng = 111_320 * Math.cos((lat * Math.PI) / 180);
        const ring = [
          [-hw, -hd],
          [hw, -hd],
          [hw, hd],
          [-hw, hd],
          [-hw, -hd],
        ].map(([u, v]) => [lng + (u * cos + v * sin) / mLng, lat + (-u * sin + v * cos) / mLat]);
        features.push({ type: "Feature", properties: { kind: "building", h: b[i + 4] }, geometry: { type: "Polygon", coordinates: [ring] } });
      }
      return { type: "FeatureCollection" as const, features };
    })
    .catch((err) => {
      cityData = null; // allow a retry on the next map
      throw err;
    });
  return cityData;
}

const EMPTY: FeatureCollection = { type: "FeatureCollection", features: [] };

/** The style starts empty; MapView fills the `city` source from loadCityData(). */
export function cityStyle(theme: MapTheme): StyleSpecification {
  const p = PALETTES[theme];
  return {
    version: 8,
    name: "hop-city",
    sources: {
      city: { type: "geojson", data: EMPTY, attribution: CITY_ATTRIBUTION },
    },
    light: { anchor: "viewport", color: theme === "dark" ? "#ffffff" : "#eef3ff", intensity: theme === "dark" ? 0.25 : 0.3, position: [1.4, 210, 40] },
    sky: {
      "sky-color": p.sky,
      "horizon-color": p.horizon,
      "fog-color": p.fog,
      "sky-horizon-blend": 0.7,
      "horizon-fog-blend": 0.6,
      "fog-ground-blend": 0.25,
      "atmosphere-blend": 0,
    },
    layers: [
      { id: "city-land", type: "background", paint: { "background-color": p.land } },
      { id: "city-sea", type: "fill", source: "city", filter: kind("sea"), paint: { "fill-color": p.sea } },
      {
        id: "city-sea-edge",
        type: "line",
        source: "city",
        filter: kind("sea"),
        paint: { "line-color": p.seaEdge, "line-width": w([10, 1], [16, 6]), "line-blur": w([10, 1], [16, 6]), "line-opacity": 0.8 },
      },
      { id: "city-beach", type: "fill", source: "city", filter: kind("beach"), paint: { "fill-color": p.beach } },
      { id: "city-park", type: "fill", source: "city", filter: kind("park"), paint: { "fill-color": p.park, "fill-outline-color": p.parkEdge } },
      {
        id: "city-river",
        type: "line",
        source: "city",
        filter: kind("river"),
        layout: { "line-cap": "round", "line-join": "round" },
        paint: { "line-color": p.river, "line-width": w([10, 2], [14, 6], [18, 26]) },
      },
      // casings first, then fills, so junctions merge cleanly
      ...(["minor", "medium", "major"] as const).map((c) => ({
        id: `city-road-${c}-casing`,
        type: "line" as const,
        source: "city",
        filter: roadClass(c),
        minzoom: c === "minor" ? 12.5 : c === "medium" ? 11 : 9,
        layout: { "line-cap": "round" as const, "line-join": "round" as const },
        paint: {
          "line-color": p.casing,
          "line-width": c === "minor" ? w([12.5, 1], [16, 7], [18, 16]) : c === "medium" ? w([11, 1.4], [16, 10], [18, 21]) : w([9, 1.6], [16, 14], [18, 26]),
        },
      })),
      {
        id: "city-road-highway-casing",
        type: "line",
        source: "city",
        filter: roadClass("highway"),
        layout: { "line-cap": "round", "line-join": "round" },
        paint: { "line-color": p.highwayCasing, "line-width": w([8, 2], [16, 20], [18, 34]) },
      },
      ...(["minor", "medium", "major"] as const).map((c) => ({
        id: `city-road-${c}`,
        type: "line" as const,
        source: "city",
        filter: roadClass(c),
        minzoom: c === "minor" ? 12.5 : c === "medium" ? 11 : 9,
        layout: { "line-cap": "round" as const, "line-join": "round" as const },
        paint: {
          "line-color": p.road,
          "line-width": c === "minor" ? w([12.5, 0.4], [16, 5], [18, 13]) : c === "medium" ? w([11, 0.6], [16, 8], [18, 18]) : w([9, 0.8], [16, 11], [18, 22]),
        },
      })),
      {
        id: "city-road-highway",
        type: "line",
        source: "city",
        filter: roadClass("highway"),
        layout: { "line-cap": "round", "line-join": "round" },
        paint: { "line-color": p.highway, "line-width": w([8, 1], [16, 15], [18, 28]) },
      },
      {
        id: "city-buildings",
        type: "fill-extrusion",
        source: "city",
        filter: kind("building"),
        minzoom: 13,
        paint: {
          "fill-extrusion-color": ["interpolate", ["linear"], ["get", "h"], 0, p.buildingLow, 30, p.buildingMid, 140, p.buildingHigh],
          "fill-extrusion-height": ["interpolate", ["linear"], ["zoom"], 13, 0, 14.2, ["get", "h"]],
          "fill-extrusion-base": 0,
          "fill-extrusion-opacity": 0.92,
          "fill-extrusion-vertical-gradient": true,
        },
      },
    ],
  };
}

